CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_voucher]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_voucher]
	(
		[apuk_applicationtype],
		[apuk_discountpercentage],
		[apuk_enddate],
		[apuk_friendlyname],
		[apuk_membergrade],
		[apuk_quantity],
		[apuk_quantityused],
		[apuk_startdate],
		[apuk_subscriptionproductid],
		[apuk_subscriptionproductid_entitytype],
		[apuk_subscriptionproductidname],
		[apuk_vouchercode],
		[apuk_voucherid],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[emailaddress],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_applicationtype],
		stg.[apuk_discountpercentage],
		stg.[apuk_enddate],
		stg.[apuk_friendlyname],
		stg.[apuk_membergrade],
		stg.[apuk_quantity],
		stg.[apuk_quantityused],
		stg.[apuk_startdate],
		stg.[apuk_subscriptionproductid],
		stg.[apuk_subscriptionproductid_entitytype],
		stg.[apuk_subscriptionproductidname],
		stg.[apuk_vouchercode],
		stg.[apuk_voucherid],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[emailaddress],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_voucher] stg
		LEFT JOIN [synapse_ce].[apuk_voucher] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
